use spore_core::{cell_part_geometry::NativeCellPart,cell_feature_projection_v1::Transform,cell_feature_first_candidate_v1::{first,Outcome},cell_feeding_b7_selection_v1::{apply,Binding,Step,Error},cell_feeding_contact_arbitration_e59b40_v1::ContactOutput};
fn row(class:u32)->NativeCellPart{NativeCellPart{word_06_is_ffff:false,class,center:[0.;3],matrix_bits:[0;9],radius:1.,tail_bits:[0;3]}}
fn transform(x:f32)->Transform{Transform{position:[x.to_bits(),0,0],scale:1f32.to_bits(),flags:0,matrix:[0;9]}}
fn initial()->ContactOutput{ContactOutput{actor_ids:[0;2],selector:0,feature_indices:[0;2],depth_bits:0,point_words:[0;3],normal_words:[0;3]}}
#[test]fn candidate_to_b7_selection_stops_at_intermediate(){let (a,b)=(row(2),row(3));let Outcome::Pending(c)=first([&a,&b],[transform(0.),transform(1.)],[11,22],[2,7],4,0,true).unwrap() else {panic!()};let binding=Binding{actor_tokens:[11,22],actor_words:[101,202],current_player_word:101,stable_disjoint:true};let Step::Submitted{selection,..}=apply(&c,binding,initial()).unwrap()else{panic!()};assert_eq!(selection.selector,19);assert_eq!(selection.actor_ids,[101,202]);assert_eq!(selection.depth_bits,1f32.to_bits());assert_eq!(selection.point_words,[0.5f32.to_bits(),0,0]);let Outcome::Pending(small)=first([&a,&b],[transform(0.),transform(0.)],[11,22],[2,7],4,0,true).unwrap()else{panic!()};assert_eq!(apply(&small,binding,initial()),Err(Error::OpaqueSmallLocals));}
